inline float ProceduralCloudDensity3D(float noiseSample,float coverage=.54f,float softness=.18f){if(!std::isfinite(noiseSample)||!std::isfinite(coverage)||!std::isfinite(softness)||softness<=0.f)return 0.f;const float value=Clamp((noiseSample-coverage)/softness,0.f,1.f);return value*value*(3.f-2.f*value);}
inline float CloudHorizonFade3D(float rayHeight){if(!std::isfinite(rayHeight))return 0.f;const float value=Clamp((rayHeight-.025f)/.18f,0.f,1.f);return value*value*(3.f-2.f*value);}
struct VolumetricCloudSettings3D {bool enabled{true};float baseAltitude{1200.f},thickness{1800.f},coverage{.52f},density{1.15f},erosion{.24f},windSpeed{18.f};uint32_t sampleCount{16};bool shadowsEnabled{true};float shadowStrength{.72f};friend constexpr bool operator==(const VolumetricCloudSettings3D&,const VolumetricCloudSettings3D&)=default;};
inline VolumetricCloudSettings3D NormalizeVolumetricCloudSettings3D(VolumetricCloudSettings3D settings){settings.baseAltitude=Clamp(std::isfinite(settings.baseAltitude)?settings.baseAltitude:1200.f,-10000.f,50000.f);settings.thickness=Clamp(std::isfinite(settings.thickness)?settings.thickness:1800.f,10.f,20000.f);settings.coverage=Clamp(std::isfinite(settings.coverage)?settings.coverage:.52f,.05f,.95f);settings.density=Clamp(std::isfinite(settings.density)?settings.density:1.15f,0.f,4.f);settings.erosion=Clamp(std::isfinite(settings.erosion)?settings.erosion:.24f,0.f,.8f);settings.windSpeed=Clamp(std::isfinite(settings.windSpeed)?settings.windSpeed:18.f,-200.f,200.f);settings.sampleCount=(std::clamp)(settings.sampleCount,4u,16u);settings.shadowStrength=Clamp(std::isfinite(settings.shadowStrength)?settings.shadowStrength:.72f,0.f,1.f);return settings;}
